import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const l="/img/chatbot_flowchart.png",b=JSON.parse('{"title":"聊天机器人","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/chatbot.md","filePath":"ai-dive/chatbot.md","lastUpdated":null}'),i={name:"ai-dive/chatbot.md"};function h(n,a,s,c,p,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="聊天机器人" tabindex="-1">聊天机器人 <a class="header-anchor" href="#聊天机器人" aria-label="Permalink to &quot;聊天机器人&quot;">​</a></h1><h2 id="nlp应用概览" tabindex="-1">NLP应用概览 <a class="header-anchor" href="#nlp应用概览" aria-label="Permalink to &quot;NLP应用概览&quot;">​</a></h2><p>NLP作为人工智能的核心技术，在机器翻译、聊天机器人、语音识别等领域都有重要的应用。</p><p>机器翻译的代表如科大讯飞的翻译机；聊天机器人例如微软小冰、Amazon Alexa；语音识别如各种智能音箱。</p><h2 id="聊天机器人系统框架" tabindex="-1">聊天机器人系统框架 <a class="header-anchor" href="#聊天机器人系统框架" aria-label="Permalink to &quot;聊天机器人系统框架&quot;">​</a></h2><p>一个完整聊天机器人的系统架构主要由唤醒、语言识别、自然语言理解、对话管理、自然语言生成、语音合成等6个部分组成。更多详细见<a href="http://www.ciotc.org/?from=timeline#/articaltwoinfo?id=20191209112501276114675&amp;ids=18" target="_blank" rel="noreferrer">8</a></p><p><img src="'+l+'" alt="聊天机器人的流程闭环7"></p><ul><li>唤醒wakeup，匹配到唤醒词后进入工作状态。</li><li>自动语音识别automatic speech recognition，ASR，负责将原始的语音信号转换成文本信息。</li><li>自然语言理解natural language understanding，NLU，负责将识别到的文本信息转换为机器可以理解的语义表示。</li><li>对话管理dialogue management，DM，负责基于当前对话的状态判断系统应该采取怎样的动作。 包括对话状态跟踪（Dialog StateTracking, DST）、对话策略（Dialogue Policy）、作为接口与后端/任务模型进行交互、提供语义表达的期望值（expections for interpretation）。 <strong>对话状态跟踪</strong>（Dialog StateTracking, DST） ：根据对话历史，维护当前对话状态，对话状态是对整个对话历史的累积语义表示，一般就是槽值对(slot-value pairs)。 <strong>对话策略</strong>（Dialogue Policy）：根据当前对话状态输出下一步系统动作。<a href="https://www.toutiao.com/i6854955754193945096/" target="_blank" rel="noreferrer">6</a></li></ul><ol><li>有适用于简单应用场景的<strong>穷举</strong>的方式，类似数据库查表的方式；</li><li>有适用于<strong>面向特定任务</strong>的对话系统的基于框架的方法；</li><li>有基于强化学习的方式，不断的更新决策策略以最大化reward；</li><li>有基于浅层神经网络和强化学习结合的方法。</li></ol><ul><li>自然语言生成natural language generation，NLG，负责将系统动作／系统回复转变成自然语言文本。</li><li>语音合成text-to-speech，TTS，负责将自然语言文本转变成语音信号输出给用户。</li></ul><h2 id="asr-10" tabindex="-1">ASR <a href="http://imgtec.eetrend.com/blog/2019/100046571.html#:~:text=%E5%AF%B9%E8%BE%93%E5%85%A5%E7%9A%84%E5%8E%9F%E5%A7%8B%E8%AF%AD%E9%9F%B3,%E2%80%9D%E8%BF%9B%E8%A1%8C%E5%88%86%E6%9E%90%EF%BC%89%E7%AD%89%E5%A4%84%E7%90%86%E3%80%82" target="_blank" rel="noreferrer">10</a> <a class="header-anchor" href="#asr-10" aria-label="Permalink to &quot;ASR [10]&quot;">​</a></h2><p>“输入——编码——解码——输出”</p><h3 id="语音输入的预处理模块" tabindex="-1">语音输入的预处理模块 <a class="header-anchor" href="#语音输入的预处理模块" aria-label="Permalink to &quot;语音输入的预处理模块&quot;">​</a></h3><p>对输入的原始语音信号进行处理，滤除掉其中的不重要信息以及背景噪声，并进行语音信号的端点检测（也就是找出语音信号的始末）、语音分帧（可以近似理解为，一段语音就像是一段视频，由许多帧的有序画面构成，可以将语音信号切割为单个的“画面”进行分析）等处理。</p><h3 id="特征提取" tabindex="-1">特征提取 <a class="header-anchor" href="#特征提取" aria-label="Permalink to &quot;特征提取&quot;">​</a></h3><p>在去除语音信号中对于语音识别无用的冗余信息后，保留能够反映语音本质特征的信息进行处理，并用一定的形式表示出来。也就是提取出反映语音信号特征的关键特征参数形成特征矢量序列，以便用于后续处理。</p><h3 id="声学模型训练" tabindex="-1">声学模型训练 <a class="header-anchor" href="#声学模型训练" aria-label="Permalink to &quot;声学模型训练&quot;">​</a></h3><p>声学模型可以理解为是对声音的建模，能够把语音输入转换成声学表示的输出，准确的说，是给出语音属于某个声学符号的概率。根据训练语音库的特征参数训练出声学模型参数。在识别时可以将待识别的语音的特征参数与声学模型进行匹配，得到识别结果。目前的主流语音识别系统多采用隐马尔可夫模型HMM进行声学模型建模。</p><h3 id="语言模型训练" tabindex="-1">语言模型训练 <a class="header-anchor" href="#语言模型训练" aria-label="Permalink to &quot;语言模型训练&quot;">​</a></h3><p>语言模型是用来计算一个句子出现概率的模型，简单地说，就是计算一个句子在语法上是否正确的概率。因为句子的构造往往是规律的，前面出现的词经常预示了后方可能出现的词语。它主要用于决定哪个词序列的可能性更大，或者在出现了几个词的时候预测下一个即将出现的词语。它定义了哪些词能跟在上一个已经识别的词的后面（匹配是一个顺序的处理过程），这样就可以为匹配过程排除一些不可能的单词。</p><p>语言建模能够有效的结合汉语语法和语义的知识，描述词之间的内在关系，从而提高识别率，减少搜索范围。对训练文本数据库进行语法、语义分析，经过基于统计模型训练得到语言模型。</p><h3 id="语音解码和搜索算法" tabindex="-1">语音解码和搜索算法 <a class="header-anchor" href="#语音解码和搜索算法" aria-label="Permalink to &quot;语音解码和搜索算法&quot;">​</a></h3><p>解码器是指语音技术中的识别过程。针对输入的语音信号，根据己经训练好的HMM声学模型、语言模型及字典建立一个识别网络，根据搜索算法在该网络中寻找最佳的一条路径，这个路径就是能够以最大概率输出该语音信号的词串，这样就确定这个语音样本所包含的文字了。所以，解码操作即指搜索算法，即在解码端通过搜索技术寻找最优词串的方法。</p><p>连续语音识别中的搜索，就是寻找一个词模型序列以描述输入语音信号，从而得到词解码序列。搜索所依据的是对公式中的声学模型打分和语言模型打分。在实际使用中，往往要依据经验给语言模型加上一个高权重，并设置一个长词惩罚分数。</p><h2 id="形态" tabindex="-1">形态 <a class="header-anchor" href="#形态" aria-label="Permalink to &quot;形态&quot;">​</a></h2><ul><li>硬件形态：智能音箱<a href="http://www.ciotc.org/?from=timeline#/articaltwoinfo?id=20191209112501276114675&amp;ids=18" target="_blank" rel="noreferrer">8</a>如amazon echo（2014年11月全球第一款）、公子小白、。</li><li>软件形态：Apple Siri、微软小冰、微软cortana、IBM watson、Google Now。</li><li>平台：谷歌、微软等公司对外提供聊天机器人框架bot framework，以sdk或saas服务的方式像第三方公司或个人开发者提供可以用于构建特定应用和领域的聊天机器人。代表：amazon Alexa（服务amazon lex）、微软luis with bot（认知服务cognitive services）、谷歌api.ai、Facebook wit.ai。</li></ul><h2 id="类别" tabindex="-1">类别 <a class="header-anchor" href="#类别" aria-label="Permalink to &quot;类别&quot;">​</a></h2><p>两类：</p><h3 id="闲聊机器人" tabindex="-1">闲聊机器人 <a class="header-anchor" href="#闲聊机器人" aria-label="Permalink to &quot;闲聊机器人&quot;">​</a></h3><ol><li>基于seq2seq模型的对话系统：根据前一句来生成后一句的回复，对话的回答局限性大，缺少对整个对话的评估，且容易陷入死循环。</li><li>基于DRL的对话系统：利用强化学习对当前生成的各种回复评估，选择reward值最高的句子。评估方式根据应用场景不同，可以设计不同的评估函数。</li><li>GAN和RL结合的对话系统：生成器生成对话，判别器评估每种结果的reward，其中各种可能的结果是采用MCTS或者策略梯度的方式。seqGAN<a href="https://github.com/LantaoYu/SeqGAN" target="_blank" rel="noreferrer">3</a>,Neural-Dialogue-Generation<a href="https://github.com/jiweil/Neural-Dialogue-Generation" target="_blank" rel="noreferrer">5</a></li></ol><h3 id="面向任务的聊天机器人" tabindex="-1">面向任务的聊天机器人 <a class="header-anchor" href="#面向任务的聊天机器人" aria-label="Permalink to &quot;面向任务的聊天机器人&quot;">​</a></h3><ol><li>基于DQN的对话系统：DM模块采用DQN模型可能结果的reward值。</li></ol><p>任务型对话系统以智能为核心的评价体系：<a href="http://www.zgcsa.org/uploads/file/20201105192719_469.pdf" target="_blank" rel="noreferrer">http://www.zgcsa.org/uploads/file/20201105192719_469.pdf</a></p><p>任务型对话系统概述<a href="https://www.taodudu.cc/news/show-1668385.html" target="_blank" rel="noreferrer">9</a></p><h2 id="项目" tabindex="-1">项目 <a class="header-anchor" href="#项目" aria-label="Permalink to &quot;项目&quot;">​</a></h2><p>基于金融-司法领域(兼有闲聊性质)的聊天机器人：<a href="https://github.com/charlesXu86/Chatbot_CN" target="_blank" rel="noreferrer">https://github.com/charlesXu86/Chatbot_CN</a></p><p>Accompany AI Chat<a href="https://github.com/EasonC13/AI_chatbot_platform" target="_blank" rel="noreferrer">13</a></p><h2 id="核心竞争力" tabindex="-1">核心竞争力？ <a class="header-anchor" href="#核心竞争力" aria-label="Permalink to &quot;核心竞争力？&quot;">​</a></h2><p>2017年9月底了，对话机器人（各种个人助理、问答系统和智能客服等）领域的情况与16年年底相比，已经有了显著的变化。</p><p>与16年业界普遍的基于规则的自然语言解析系统相比，目前AI领域第一二梯队的公司基本都已经拥有了较为成熟且可商业化的基于深度学习的自然语言解析系统。就公司而言，对自然语言解析技术的研究已经到了边际效用递减的程度，可做的虽然还很多，比如更深层次的句法/语义分析、与知识图谱的结合等，但解析技术已经不再构成对话机器人产品的核心竞争力。<a href="https://www.jianshu.com/p/6b83e669cd63" target="_blank" rel="noreferrer">12</a></p><h2 id="困境" tabindex="-1">困境 <a class="header-anchor" href="#困境" aria-label="Permalink to &quot;困境&quot;">​</a></h2><p>亚马逊的Alexa还没有找到能让用户玩上20分钟的应用。<a href="https://www.zhihu.com/question/264342280/answer/279782691" target="_blank" rel="noreferrer">14</a></p><h2 id="更多" tabindex="-1">更多 <a class="header-anchor" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h2><p>认真的聊一聊对话系统（任务型、检索式、生成式对话论文与工具串讲） - 夕小瑶的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/83825070" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/83825070</a></p><p>聊天对话类的Ai未来的产品发展方向是什么？ - 知乎 <a href="https://www.zhihu.com/question/484027134" target="_blank" rel="noreferrer">https://www.zhihu.com/question/484027134</a></p>',45)])])}const f=e(i,[["render",h]]);export{b as __pageData,f as default};
